-- ---------------------------------------------------------------------------
-- Lock the new tables down (no policies; the RPCs are SECURITY DEFINER).
-- ---------------------------------------------------------------------------
alter table public.festival_dates      enable row level security;
alter table public.festival_categories enable row level security;

-- ---------------------------------------------------------------------------
-- Festival calendar: every active festival with its next occurrence.
-- ---------------------------------------------------------------------------
create or replace function public.get_festival_calendar()
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
    with base as (
        select
            fc.id, fc.slug, fc.name, fc.name_ne, fc.emoji, fc.description,
            fc.display_order, fc.mood_tags,
            (select count(*) from public.songs s
              where s.festival_id = fc.id and s.publication_status = 'published') as song_count
        from public.festival_categories fc
        where fc.is_active
    ),
    occ as (
        select
            b.id,
            coalesce(future.start_date, past.start_date + interval '1 year')::date as start_date,
            coalesce(future.end_date,   past.end_date   + interval '1 year')::date as end_date,
            (future.start_date is null and past.start_date is not null) as is_estimated
        from base b
        left join lateral (
            select fd.start_date, fd.end_date
            from public.festival_dates fd
            where fd.festival_id = b.id and fd.end_date >= current_date
            order by fd.start_date asc limit 1
        ) future on true
        left join lateral (
            select fd.start_date, fd.end_date
            from public.festival_dates fd
            where fd.festival_id = b.id
            order by fd.start_date desc limit 1
        ) past on true
    )
    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'id', b.id, 'slug', b.slug, 'name', b.name, 'name_ne', b.name_ne,
                'emoji', b.emoji, 'description', b.description,
                'display_order', b.display_order, 'mood_tags', to_jsonb(b.mood_tags),
                'song_count', b.song_count,
                'start_date', o.start_date, 'end_date', o.end_date,
                'days_until_start', (o.start_date - current_date),
                'days_until_end', (o.end_date - current_date),
                'is_active_window', (o.start_date <= current_date and current_date <= o.end_date),
                'is_imminent', (o.start_date >= current_date and (o.start_date - current_date) <= 20),
                'is_estimated', o.is_estimated
            )
            order by
                case when o.start_date <= current_date and current_date <= o.end_date then 0 else 1 end,
                o.start_date asc,
                b.display_order asc
        ),
        '[]'::jsonb
    )
    from base b
    join occ o on o.id = b.id;
$$;

comment on function public.get_festival_calendar() is 'Active festivals ordered by the soonest upcoming occurrence, with countdown fields.';

-- ---------------------------------------------------------------------------
-- Festival playlist: dedicated songs first, then vibe-matched songs, then a
-- trending festive layer (popular + recent festive tracks from across the
-- catalog, so "the thing playing right now" leads the mix). Every festival
-- therefore always has a full, playable set even before it has many uploads.
-- ---------------------------------------------------------------------------
create or replace function public.get_festival_songs(p_festival_slug text, p_limit int default 24)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
    v_festival bigint;
    v_tags     text[];
    v_limit    int := least(greatest(coalesce(p_limit, 24), 1), 100);
    v_count    bigint;
    v_results  jsonb;
begin
    select id, mood_tags into v_festival, v_tags
    from public.festival_categories
    where slug = p_festival_slug and is_active;

    if v_festival is null then
        return jsonb_build_object('count', 0, 'dedicated_count', 0, 'results', '[]'::jsonb);
    end if;

    select count(*) into v_count
    from public.songs s
    where s.festival_id = v_festival and s.publication_status = 'published';

    with direct as (
        select s.id, s.play_count, s.release_year, 0 as tier, 'festival'::text as source
        from public.songs s
        where s.festival_id = v_festival and s.publication_status = 'published'
    ),
    vibe as (
        select s.id, s.play_count, s.release_year, 1 as tier, 'vibe'::text as source
        from public.songs s
        where s.publication_status = 'published'
          and s.festival_id is distinct from v_festival
          and coalesce(cardinality(v_tags), 0) > 0
          and s.mood_tags ?| v_tags
    ),
    trending as (
        select s.id, s.play_count, s.release_year, 2 as tier, 'trending'::text as source
        from public.songs s
        where s.publication_status = 'published'
          and (s.mood_tags ? 'festive' or s.festival_id is not null)
    ),
    picked as (
        select id, play_count, release_year, tier, source from direct
        union all
        select id, play_count, release_year, tier, source from vibe
        union all
        select id, play_count, release_year, tier, source from trending
    ),
    best as (
        select distinct on (id) id, play_count, release_year, tier, source
        from picked
        order by id, tier asc
    )
    select coalesce(
        jsonb_agg(sp.song order by sp.tier asc, sp.play_count desc nulls last, sp.release_year desc nulls last, sp.id desc),
        '[]'::jsonb
    )
    into v_results
    from (
        select b.tier, b.source, s.id, s.play_count, s.release_year,
            jsonb_build_object(
                'id', s.id,
                'title', s.title,
                'title_ne', s.title_ne,
                'artist_name', a.display_name,
                'artist_name_ne', a.display_name_ne,
                'primary_genre_name', g.name,
                'primary_genre_category', g.category,
                'mood_tags', s.mood_tags,
                'release_year', s.release_year,
                'duration_seconds', s.duration_seconds,
                'artwork_url', s.artwork_url,
                'play_count', s.play_count,
                'is_featured', s.is_featured,
                'featured_order', s.featured_order,
                'playback_provider', s.playback_provider,
                'provider_video_id', s.provider_video_id,
                'provider_url', s.provider_url,
                'source', b.source
            ) as song
        from (
            select id, play_count, release_year, tier, source
            from best
            order by tier asc, play_count desc nulls last, release_year desc nulls last, id desc
            limit v_limit
        ) b
        join public.songs s on s.id = b.id
        join public.artists a on a.id = s.artist_id
        left join public.genres g on g.id = s.primary_genre_id
    ) sp;

    return jsonb_build_object(
        'count', coalesce(jsonb_array_length(v_results), 0),
        'dedicated_count', v_count,
        'results', v_results
    );
end;
$$;

comment on function public.get_festival_songs(text, int) is 'Festival playlist: dedicated songs, then vibe-matched songs, then trending festive tracks.';

commit;


-- ===========================================================================
-- 3. 0009_song_requests.sql
-- ===========================================================================
-- Purano Dhun — 0009_song_requests.sql
--
-- "Recommend a song" feature: an unauthenticated visitor can suggest a song we
-- should add to the catalog. Mirrors the takedown workflow (0006) so the abuse
-- story is identical:
--
--   * the table is RLS-locked (0004) and only reachable through SECURITY DEFINER
--     RPCs, so no email or internal note is ever exposed to the browser;
--   * submissions are validated first, then throttled (8/hour per email or per
--     anonymous listener session);
--   * every accepted suggestion is written to the audit trail;
--   * a small public feed powers a "recently suggested" list on the site, while
--     the full queue (with requester contact + admin notes) is admin-only.
--
-- Idempotent: safe to re-run, and safe to apply on a database that already has
-- the festival feature (it does not depend on 0007/0008).

begin;

-- ---------------------------------------------------------------------------
-- Table
-- ---------------------------------------------------------------------------

create table if not exists public.song_requests (
    id              bigint generated by default as identity primary key,
    title           text not null,
    artist          text not null default '',
    youtube_url     text not null default '',
    festival_id     bigint references public.festival_categories (id) on delete set null,
    genre_id        bigint references public.genres (id) on delete set null,
    note            text not null default '',
    requester_name  text not null,
    requester_email text not null default '',
    status          text not null default 'pending',
    admin_notes     text not null default '',
    reporter_id     uuid,
    created_at      timestamptz not null default now(),
    resolved_at     timestamptz,
    constraint song_request_status_check
        check (status in ('pending', 'under_review', 'added', 'rejected'))
);
create index if not exists song_requests_status_idx on public.song_requests (status);
create index if not exists song_requests_created_idx on public.song_requests (created_at);
create index if not exists song_requests_email_time_idx on public.song_requests (requester_email, created_at);
create index if not exists song_requests_reporter_time_idx on public.song_requests (reporter_id, created_at);

alter table public.song_requests enable row level security;

-- ---------------------------------------------------------------------------
-- 1. submit_song_request: validated, throttled, audited public submission
-- ---------------------------------------------------------------------------

create or replace function public.submit_song_request(
    p_title          text,
    p_artist         text default '',
    p_youtube_url    text default '',
    p_festival_slug  text default '',
    p_genre_id       bigint default null,
    p_note           text default '',
    p_requester_name text default '',
    p_requester_email text default ''
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
    v_request_id bigint;
    v_uid        uuid := auth.uid();
    v_email      text;
    v_url        text := btrim(coalesce(p_youtube_url, ''));
    v_slug       text := btrim(coalesce(p_festival_slug, ''));
    v_festival   bigint;
    v_recent     integer;
begin
    -- --- validation (before the throttle, so bad input never probes it) -----
    if p_title is null or btrim(p_title) = '' then
        raise exception 'title: This field is required.';
    end if;
    if length(btrim(p_title)) > 300 then
        raise exception 'title: Keep the song title under 300 characters.';
    end if;
    if p_requester_name is null or btrim(p_requester_name) = '' then
        raise exception 'requester_name: This field is required.';
    end if;
    if length(btrim(p_requester_name)) > 200 then
        raise exception 'requester_name: Keep your name under 200 characters.';
    end if;

    v_email := lower(btrim(coalesce(p_requester_email, '')));
    if v_email <> '' then
        if length(v_email) > 320 or v_email !~ '^[^@]+@[^@]+\.[^@]+$' then
            raise exception 'requester_email: Enter a valid email address.';
        end if;
    end if;

    if v_url <> '' and v_url !~* '^https?://(www\.|m\.|music\.)?(youtube\.com|youtu\.be)/' then
        raise exception 'youtube_url: Enter a valid YouTube link.';
    end if;

    if v_slug <> '' then
        select id into v_festival
        from public.festival_categories
        where slug = v_slug and is_active
        limit 1;
        if v_festival is null then
            raise exception 'festival_slug: Unknown festival.';
        end if;
    end if;

    if p_genre_id is not null and not exists (select 1 from public.genres where id = p_genre_id) then
        raise exception 'genre_id: Unknown genre.';
    end if;

    -- --- throttle: 8 suggestions/hour per email or listener session ---------
    select count(*) into v_recent
    from public.song_requests
    where created_at > now() - interval '1 hour'
      and ((v_email <> '' and requester_email = v_email)
           or (v_uid is not null and reporter_id = v_uid));
    if v_recent >= 8 then
        raise exception 'Too many suggestions from this identity in the last hour. Please try again later.';
    end if;

    insert into public.song_requests
        (title, artist, youtube_url, festival_id, genre_id, note,
         requester_name, requester_email, reporter_id)
    values (
        left(btrim(p_title), 300),
        left(btrim(coalesce(p_artist, '')), 200),
        left(v_url, 500),
        v_festival,
        p_genre_id,
        left(coalesce(p_note, ''), 2000),
        left(btrim(p_requester_name), 200),
        v_email,
        v_uid
    )
    returning id into v_request_id;

    insert into public.audit_logs (actor_username, action, target_model, target_id, details)
    values (
        'public_listener',
        'SONG_REQUEST_SUBMITTED',
        'SongRequest',
        v_request_id::text,
        jsonb_build_object(
            'title', left(btrim(p_title), 300),
            'festival_slug', v_slug,
            'requester_email', v_email
        )
    );

    return jsonb_build_object(
        'message', 'Thanks! Your suggestion has been logged for review.',
        'request_id', v_request_id
    );
end;
$$;

-- ---------------------------------------------------------------------------
-- 2. get_song_requests_recent: public, contact-free "community suggestions"
-- ---------------------------------------------------------------------------

create or replace function public.get_song_requests_recent(p_limit integer default 6)
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
    select coalesce(jsonb_agg(payload order by created_at desc), '[]'::jsonb)
    from (
        select
            sr.created_at,
            jsonb_build_object(
                'id', sr.id,
                'title', sr.title,
                'artist', sr.artist,
                'festival_name', fc.name,
                'festival_name_ne', fc.name_ne,
                'festival_emoji', fc.emoji,
                'status', sr.status,
                'created_at', sr.created_at
            ) as payload
        from public.song_requests sr
        left join public.festival_categories fc on fc.id = sr.festival_id
        where sr.status in ('pending', 'under_review', 'added')
        order by sr.created_at desc
        limit greatest(0, least(coalesce(p_limit, 6), 24))
    ) t;
$$;

-- ---------------------------------------------------------------------------
-- 3. admin_song_requests: the full moderation queue (admin-only)
-- ---------------------------------------------------------------------------

create or replace function public.admin_song_requests(
    p_status text default '',
    p_search text default ''
)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
    if not public.is_admin() then
        raise exception 'Admin access required';
    end if;

    return (
        select jsonb_build_object(
            'count', count(*)::bigint,
            'results', coalesce(jsonb_agg(payload order by created_at desc), '[]'::jsonb),
            'available_statuses', '["pending", "under_review", "added", "rejected"]'::jsonb
        )
        from (
            select
                sr.created_at as created_at,
                jsonb_build_object(
                    'id', sr.id,
                    'title', sr.title,
                    'artist', sr.artist,
                    'youtube_url', sr.youtube_url,
                    'festival', sr.festival_id,
                    'festival_name', fc.name,
                    'festival_emoji', fc.emoji,
                    'genre', sr.genre_id,
                    'note', sr.note,
                    'requester_name', sr.requester_name,
                    'requester_email', sr.requester_email,
                    'status', sr.status,
                    'admin_notes', sr.admin_notes,
                    'created_at', sr.created_at,
                    'resolved_at', sr.resolved_at
                ) as payload
            from public.song_requests sr
            left join public.festival_categories fc on fc.id = sr.festival_id
            where (coalesce(p_status, '') = '' or sr.status = p_status)
              and (
                  coalesce(p_search, '') = '' or
                  sr.title ilike '%' || p_search || '%' or
                  sr.artist ilike '%' || p_search || '%' or
                  sr.requester_name ilike '%' || p_search || '%' or
                  sr.requester_email ilike '%' || p_search || '%'
              )
        ) t
    );
end;
$$;

-- ---------------------------------------------------------------------------
-- 4. admin_song_request_action: resolve one suggestion (admin-only)
-- ---------------------------------------------------------------------------

create or replace function public.admin_song_request_action(
    p_id bigint,
    p_status text,
    p_admin_notes text default ''
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
    sr public.song_requests;
begin
    if not public.is_admin() then
        raise exception 'Admin access required';
    end if;

    select * into sr from public.song_requests where id = p_id;
    if not found then
        raise exception 'Suggestion not found';
    end if;
    if p_status not in ('pending', 'under_review', 'added', 'rejected') then
        raise exception 'Invalid status';
    end if;

    update public.song_requests set
        status = p_status,
        admin_notes = left(coalesce(p_admin_notes, ''), 2000),
        resolved_at = case
            when p_status in ('added', 'rejected') then now()
            else null
        end
    where id = p_id;

    perform public._audit('SONG_REQUEST_' || upper(p_status), 'SongRequest', p_id::text, jsonb_build_object(
        'title', sr.title,
        'notes', left(coalesce(p_admin_notes, ''), 2000)
    ));

    return jsonb_build_object(
        'id', p_id,
        'status', p_status,
        'admin_notes', left(coalesce(p_admin_notes, ''), 2000)
    );
end;
$$;

commit;


